mapper.select:
select * from general_recruitPosition
left join  general_industryMap on general_recruitPosition.recruitPosition_industryCode = general_industryMap.industryMap_industryCode
where general_recruitPosition.recruitPosition_id = #{recruitPositionId}

SELECT rp.recruitPosition_id AS recruitPositionId, rp.recruitPosition_name AS recruitPositionName, rp.recruitPosition_industryCode AS recruitPositionIndustryCode, -- 连表字段：行业名称（从行业映射表查询） gim.industryMap_industryName AS recruitPositionIndustryName, rp.recruitPosition_minMonthSalary AS minMonthSalary, rp.recruitPosition_maxMonthSalary AS maxMonthSalary, rp.recruitPosition_weekWorkDayNum AS weekWorkDayNum, rp.recruitPosition_goodWelfare AS goodWelfare, rp.recruitPosition_createdTime AS createdTime, rp.recruitPosition_updatedTime AS updatedTime FROM general_recruitPosition rp -- 招聘岗位表别名rp -- 连表：通用行业映射表（别名gim），LEFT JOIN避免行业编码无效时丢失岗位数据 LEFT JOIN general_industryMap gim ON rp.recruitPosition_industryCode = gim.industryMap_industryCode
AND rp.recruitPosition_name LIKE CONCAT('%', #{query.recruitPositionName}, '%')
AND rp.recruitPosition_industryCode = #{query.recruitPositionIndustryCode}
AND rp.recruitPosition_minMonthSalary >= #{query.minMonthSalary}
AND rp.recruitPosition_maxMonthSalary <= #{query.maxMonthSalary}
AND rp.recruitPosition_weekWorkDayNum = #{query.weekWorkDayNum}
ORDER BY rp.recruitPosition_updatedTime DESC
